from __future__ import absolute_import

import logging
import psutil
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v22r2


class Software(v22r2.Software):
    """
    The class corresponding to software page on selenium_sbts web, all operations under software
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Software, self).__init__(driver, download_checker)
        self._software_update = SoftwareUpdatePage(driver, download_checker)


class SoftwareUpdatePage(v22r2.software.SoftwareUpdatePage):

    def __init__(self, driver, download_checker):
        super(SoftwareUpdatePage, self).__init__(driver, download_checker)
        self._view_panel = SoftwareUpdatePageViewPanel(driver, download_checker)

    def software_update(self, is_activate, timeout, start_enable_timeout, sw_active_type=None):
        self._view_panel.software_update(is_activate, timeout, start_enable_timeout, sw_active_type=sw_active_type)


class SoftwareUpdatePageViewPanel(v22r2.software.SoftwareUpdatePageViewPanel):

    _ALL_SW_ACTIVE_TYPE = "All"
    _RU_SW_ONLY_SW_ACTIVE_TYPE = "RuSwOnly"

    _RU_SW_ONLY_RAIDO_XPATH = "//input[@value='RuSwOnly']"
    _RU_SW_ONLY_RAIDO_SELECTED_XPATH = "//input[@value='RuSwOnly' and contains(@class, 'ng-valid-parse')]"

    _ALL_RAIDO_XPATH = "//input[@value='All']"
    _ALL_RAIDO_SELECTED_XPATH = "//input[@value='All' and contains(@class, 'ng-valid-parse')]"

    def software_update(self, is_activate, timeout, start_enable_timeout, sw_active_type=None):
        logging.info("package type is {}".format(self._PACKAGE_TYPE))
        if self.package_type != self._EXTERNAL_DEVICES and self.package_type != self._ORU_TYPE:
            self.select_checkbox_by_specified_status(is_activate, self._ACTIVATE_CHECKBOX_SELECTED_XPATH,
                                                     self._ACTIVATE_CHECKBOX_XPATH)
            if is_activate:
                self._select_sw_active_type(sw_active_type)

        if self.package_type == self._ORU_TYPE:
            self.select_checkbox_by_specified_status(True, self._RESET_ORU_RADIO_SELECTED_XPATH,
                                                     self._RESET_ORU_RADIO_CHECKBOX_XPATH)

        self.click_enabled_element_after_visible((By.XPATH, self._START_UPDATE_BUTTON_XPATH), start_enable_timeout)
        logging.info('cpu use {} percent, memory use {} percent'.format(psutil.cpu_percent(),
                                                                        psutil.virtual_memory().percent))

        if self.package_type == self._PACKAGE_TYPE_SITE:
            self.operate_reload_modal(operation='Close', timeout=timeout)

    def _select_sw_active_type(self, sw_active_type):
        if not sw_active_type:
            logging.info("sw active type is {}, no action here".format(sw_active_type))
            return

        type_value = sw_active_type.replace(" ", "").lower()
        if type_value == self._ALL_SW_ACTIVE_TYPE.lower():
            if not self.element_exists((By.XPATH, self._ALL_RAIDO_SELECTED_XPATH)):
                raido_element = self._driver.find_elements_by_xpath(self._ALL_RAIDO_XPATH)[0]
                self._driver.execute_script("arguments[0].click();", raido_element)
                logging.info("selected all sw active type")
        elif type_value == self._RU_SW_ONLY_SW_ACTIVE_TYPE.lower():
            if not self.element_exists((By.XPATH, self._RU_SW_ONLY_RAIDO_SELECTED_XPATH)):
                raido_element = self._driver.find_elements_by_xpath(self._RU_SW_ONLY_RAIDO_XPATH)[0]
                self._driver.execute_script("arguments[0].click();", raido_element)
                logging.info("selected ru sw only sw active type")
        else:
            logging.info("sw active type is {}, no supported".format(sw_active_type))
